import zipfile,email,pathlib,hashlib,json,urllib.request,concurrent.futures
root=pathlib.Path(__file__).resolve().parents[1]; wheels=list((root/'.browser-wheels').glob('*.whl'))
def record(p):
 with zipfile.ZipFile(p) as z:
  meta=email.message_from_bytes(z.read(next(n for n in z.namelist() if n.endswith('.dist-info/METADATA'))))
  files={n:hashlib.sha256(z.read(n)).hexdigest() for n in z.namelist() if n in ['browser_use/cli.py','browser_use/logging_config.py','browser_use/config.py','browser_harness/helpers.py','browser_harness/daemon.py','browser_harness/run.py','browser_harness/admin.py','browser_harness/paths.py','browser_harness/_ipc.py','browser_harness/telemetry.py','dotenv/main.py']}
  if meta['Name'] in ['browser-use','browser-harness']:
   license=next(n for n in z.namelist() if '.dist-info/' in n and n.endswith('/LICENSE'))
   (root/'docs/licenses'/f"{meta['Name']}-MIT.txt").write_bytes(z.read(license))
  data=json.load(urllib.request.urlopen(f"https://pypi.org/pypi/{meta['Name']}/{meta['Version']}/json"))
  item=next(n for n in data['urls'] if n['filename']==p.name)
  sha=hashlib.sha256(p.read_bytes()).hexdigest(); assert sha==item['digests']['sha256']
  return dict(name=meta['Name'].lower(),version=meta['Version'],filename=p.name,url=item['url'],sha256=sha,license=meta['License-Expression'] or meta['License'] or 'unknown',licenseAudit='unknown',leafSources=files)
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool: rows=sorted(pool.map(record,wheels),key=lambda n:n['name'])
lock='# Generated by uv 0.12.19; selected Linux x86_64 CPython 3.12 wheels only.\n'+''.join(f"{r['name']}=={r['version']} --hash=sha256:{r['sha256']}\n" for r in rows)
(root/'requirements/browser/linux-x86_64-cp312.lock').write_text(lock)
manifest=dict(schema='avo.browser-runtime.v1',python='3.12.3',soabi='cpython-312-x86_64-linux-gnu',platform='linux',machine='x86_64',resolver='uv 0.12.19',lockSha256=hashlib.sha256(lock.encode()).hexdigest(),distributions=rows)
manifest['upstream']={'browser-use':{'tag':'0.13.11','commit':'914c59bdd4acd50e9628a97a96a3919313aebc85'},'browser-harness':{'tag':'v0.1.13','commit':'c24e5072ee66f8499bacd663f4f4bcb089bc4492'},'python-dotenv':{'version':'1.2.2','disableFlagCommit':'36004e0e34be7665ff2b11a8a4005144f76f176d'}}
(root/'requirements/browser/runtime.json').write_text(json.dumps(manifest,indent=2)+'\n')
